import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { peopleKey } from './usePeople';

/**
 * Paste lines of name,grade,terms,contact (the last two may be absent or blank): a person per line,
 * in order, each as the person form would add them. Every line is checked by the form's rules
 * first, and a name or contact repeated in the paste is refused: one refused line refuses the whole
 * import. Shows how many were added; the count goes while the next press runs.
 */
function ImportPeople({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const importing = useMutation({
    mutationFn: (t: string) =>
      postJson<{ added: number }>(`/api/sheets/${encodeURIComponent(sheet)}/import-people`, { text: t, user }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });
  return (
    <section data-testid="import-panel">
      <label>
        Import people (name,grade,terms,contact per line)
        <br />
        <textarea
          data-testid="import-people"
          rows={4}
          cols={50}
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            importing.reset();
          }}
        />
      </label>
      <br />
      <button
        type="button"
        data-testid="import-submit"
        disabled={importing.isPending}
        onClick={() => {
          importing.reset();
          importing.mutate(text);
        }}
      >
        Import people
      </button>
      {importing.isSuccess && (
        <span>
          {' '}
          Added <strong data-testid="import-added">{importing.data.added}</strong>
        </span>
      )}
      {importing.isError && (
        <span data-testid="import-error" role="alert">
          {' '}
          Nothing was imported:{' '}
          {importing.error instanceof HttpError && importing.error.body
            ? importing.error.body
            : 'every line needs a person the person form would accept.'}
        </span>
      )}
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 10.5, Component: ImportPeople });
# OfficeFloor REST wiring

Domain REST endpoints are declared here as OfficeFloor YAML, served by the
`officefloor-rest-spring-boot-4-starter` inside the Spring Boot host. Put them under `rest/api/` so
their paths start with `/api/` — `SpaConfig` only lets `/api/*` reach the backend; a non-`/api/`
path returns the SPA's `index.html` instead of your endpoint. Directory nesting maps to path
segments, so `rest/api/owners.GET.yml` → `GET /api/owners`. Each route is its own file:

```
# officefloor/rest/api/<path>.GET.yml   (or .POST.yml, {param}.GET.yml, ...)
service:
  class: net.officefloor.hq.app.<SomeLogic>   # a class with a service(...) method
```

The logic class's `service(...)` method takes injected dependencies (Spring `@Service` beans, the
data layer) and a `net.officefloor.web.ObjectResponse<T>` to send the response.

(The `/actuator/health` readiness endpoint is Spring-side — Actuator — not an OfficeFloor route.)
